/**
 * Class-name helper for the app shell.
 *
 * Components generated by the shadcn registry import `cn` from the `cn`
 * package directly (clsx + tailwind-merge semantics, compiled). This module
 * re-exports the same helper under the `@/lib/utils` alias so application
 * code has one obvious import site.
 */
export { cn } from 'cn'
